import { AuthService } from '../modules/auth/auth.service';
import { db } from '../../infra/db';
import { users, sessions } from '../../infra/db/schema';
import { eq } from 'drizzle-orm';
import { redisClient } from '../../infra/redis';
import { ErrorCodes } from '@nythera/shared';

describe('AuthService', () => {
  const email = 'test@example.com';
  const password = 'password123';
  const wrongPassword = 'wrong';

  beforeAll(async () => {
    // Clean up before tests
    await db.delete(users).where(eq(users.email, email));
    await redisClient.flushall();
  });

  afterAll(async () => {
    await db.delete(users).where(eq(users.email, email));
    await redisClient.flushall();
  });

  it('should register a new user', async () => {
    const authService = new AuthService();
    const user = await authService.register(email, password);
    expect(user).toHaveProperty('id');
    expect(user.email).toBe(email);
    // Check that the user exists in the database
    const dbUser = await db.select().from(users).where(eq(users.email, email));
    expect(dbUser).toHaveLength(1);
    expect(dbUser[0].email).toBe(email);
    // Password should be hashed
    expect(dbUser[0].password_hash).not.toBe(password);
  });

  it('should not register an existing user', async () => {
    const authService = new AuthService();
    await expect(authService.register(email, password)).rejects.toMatchObject({
      code: ErrorCodes.AUTH_USER_EXISTS,
    });
  });

  it('should login with correct credentials', async () => {
    const authService = new AuthService();
    const result = await authService.login(email, password);
    expect(result).toHaveProperty('token');
    expect(result.user).toHaveProperty('id');
    expect(result.user.email).toBe(email);
    // Check that session exists in database
    const session = await db.select().from(sessions).where(eq(sessions.token, result.token));
    expect(session).toHaveLength(1);
    // Check that session exists in Redis
    const redisUserId = await redisClient.get(`session:${result.token}`);
    expect(redisUserId).toBe(result.user.id);
  });

  it('should not login with wrong password', async () => {
    const authService = new AuthService();
    await expect(authService.login(email, wrongPassword)).rejects.toMatchObject({
      code: ErrorCodes.AUTH_INVALID_CREDENTIALS,
    });
  });

  it('should rate limit login attempts', async () => {
    const authService = new AuthService();
    // First 5 attempts with wrong password should fail with invalid credentials
    for (let i = 0; i < 5; i++) {
      await expect(authService.login(email, wrongPassword)).rejects.toMatchObject({
        code: ErrorCodes.AUTH_INVALID_CREDENTIALS,
      });
    }
    // The 6th attempt should be rate limited
    await expect(authService.login(email, wrongPassword)).rejects.toMatchObject({
      code: ErrorCodes.AUTH_RATE_LIMIT_EXCEEDED,
    });
  });

  it('should logout and clear session', async () => {
    const authService = new AuthService();
    const loginResult = await authService.login(email, password);
    const token = loginResult.token;
    // Ensure session exists
    let session = await db.select().from(sessions).where(eq(sessions.token, token));
    expect(session).toHaveLength(1);
    let redisUserId = await redisClient.get(`session:${token}`);
    expect(redisUserId).toBe(loginResult.user.id);

    // Logout
    await authService.logout(token);

    // Session should be deleted from DB
    session = await db.select().from(sessions).where(eq(sessions.token, token));
    expect(session).toHaveLength(0);
    // Session should be deleted from Redis
    redisUserId = await redisClient.get(`session:${token}`);
    expect(redisUserId).toBeNull();
  });

  it('should validate token and return user info', async () => {
    const authService = new AuthService();
    const loginResult = await authService.login(email, password);
    const token = loginResult.token;
    const payload = await authService.validateToken(token);
    expect(payload).not.toBeNull();
    expect(payload.userId).toBe(loginResult.user.id);
  });

  it('should return null for invalid token', async () => {
    const authService = new AuthService();
    const payload = await authService.validateToken('invalid-token');
    expect(payload).toBeNull();
  });
});

import { CharacterService } from '../modules/character/character.service';
import { db } from '../../infra/db';
import { users, characters } from '../../infra/db/schema';
import { eq } from 'drizzle-orm';
import { ContentService } from '../content/content.service';
import { ErrorCodes } from '@nythera/shared';

describe('CharacterService', () => {
  const userId = 'user-id-for-test';
  const actorTemplateId = 1;
  const name = 'Test Character';

  // We'll need to create a user first
  let authUserId: string;

  beforeAll(async () => {
    // Clean up before tests
    await db.delete(characters);
    await db.delete(users);

    // Create a test user
    const [user] = await db.insert(users).values({
      id: 'user-id-for-test',
      email: 'test@example.com',
      password_hash: 'hashed-password', // we don't care about the actual hash for this test
    }).returning();
    authUserId = user.id;

    // We also need to have some content in the content tables for the service to work.
    // We'll insert a minimal content version and set it as active.
    // We'll do this in a beforeEach or beforeAll? We'll do it in beforeAll for now.
    // We'll insert a draft, publish it, and set it as active.

    // We'll create a minimal payload with Actors and Classes.
    const payload = {
      Actors: [
        null, // index 0
        { id: 1, name: 'Warrior', nickname: '', profile: '', classId: 1, level: 1, // we don't have params yet, but we'll add empty arrays for safety
          // We'll add the parameters as per RM MV: [hp, mp, atk, def, mat, mdf, agi, luk]
          params: [100, 10, 10, 5, 5, 5, 5, 5] },
      ],
      Classes: [
        null, // index 0
        { id: 1, name: 'Warrior', // we'll add some class parameters and learning, etc.
          // We'll add the class parameters (for level 1) and maybe leave learning empty.
          params: [100, 10, 10, 5, 5, 5, 5, 5],
          learns: [] },
      ],
      // We'll also include the other required files as empty arrays to avoid errors.
      Skills: [null],
      Items: [null],
      Weapons: [null],
      Armors: [null],
      Enemies: [null],
      Troops: [null],
      States: [null],
      System: {}, // empty system
    };

    // We'll use the content service to import and publish.
    const contentService = new ContentService();
    const importResult = await contentService.importDraft(payload);
    await contentService.publishLatestDraft();
  });

  afterAll(async () => {
    await db.delete(characters);
    await db.delete(users);
    // We'll also clean up the content tables? We'll leave it for now.
  });

  it('should create a character with valid actor template id', async () => {
    const characterService = new CharacterService();
    const character = await characterService.createCharacter(userId, actorTemplateId, name);
    expect(character).toHaveProperty('id');
    expect(character.user_id).toBe(userId);
    expect(character.actor_template_id).toBe(actorTemplateId);
    expect(character.name).toBe(name);
    expect(character.base_stats).toHaveProperty('actor');
    expect(character.base_stats).toHaveProperty('class');
    // Check that the base stats contain the actor and class we expect.
    expect(character.base_stats.actor.id).toBe(1);
    expect(character.base_stats.actor.name).toBe('Warrior');
    expect(character.base_stats.class.id).toBe(1);
    expect(character.base_stats.class.name).toBe('Warrior');
  });

  it('should not create a character with unknown actor template id', async () => {
    const characterService = new CharacterService();
    await expect(characterService.createCharacter(userId, 999, name)).rejects.toMatchObject({
      code: ErrorCodes.CHARACTER_ACTOR_NOT_FOUND,
    });
  });

  it('should get characters by user id', async () => {
    const characterService = new CharacterService();
    // First create a character
    await characterService.createCharacter(userId, actorTemplateId, name);
    const characters = await characterService.getCharactersByUserId(userId);
    expect(characters).toHaveLength(1);
    expect(characters[0].name).toBe(name);
  });

  it('should get a character by id', async () => {
    const characterService = new CharacterService();
    const created = await characterService.createCharacter(userId, actorTemplateId, name);
    const fetched = await characterService.getCharacterById(created.id, userId);
    expect(fetched.id).toBe(created.id);
    expect(fetched.name).toBe(name);
  });

  it('should not get a character by id for another user', async () => {
    const characterService = new CharacterService();
    // Create a character for the test user
    const created = await characterService.createCharacter(userId, actorTemplateId, name);
    // Try to fetch it with a different user id
    await expect(characterService.getCharacterById(created.id, 'different-user-id')).rejects.toMatchObject({
      code: ErrorCodes.CHARACTER_NOT_FOUND,
    });
  });
});

import { FastifyInstance } from 'fastify';
import contentPlugin from './modules/content/content.plugin';
import authPlugin from './modules/auth/auth.plugin';
import characterPlugin from './modules/character/character.plugin';

const server: FastifyInstance = require('fastify')({ logger: true });

// Register plugins
server.register(contentPlugin);
server.register(authPlugin);
server.register(characterPlugin);

server.get('/health', async () => {
  return { status: 'ok' };
});

const start = async () => {
  try {
    await server.listen({ port: 3000, host: '0.0.0.0' });
    server.log.info(`Server listening on ${server.server.address()}`);
  } catch (err) {
    server.log.error(err);
    process.exit(1);
  }
};

start();

import { pgTable, pgSchema, varchar, timestamp, jsonb, integer, primaryKey, pgEnum } from 'drizzle-orm/pg-core';

// Content schema (existing)
export const contentSchema = pgSchema('content');

export const contentDrafts = contentSchema.table('content_drafts', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  payload: jsonb('payload').notNull(),
  hash: varchar('hash', { length: 64 }).notNull(),
  validation_errors: jsonb('validation_errors'),
  created_at: timestamp('created_at').notNull().defaultNow(),
});

export const contentVersions = contentSchema.table('content_versions', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  version: integer('version').notNull().unique(),
  payload: jsonb('payload').notNull(),
  hash: varchar('hash', { length: 64 }).notNull(),
  published_at: timestamp('published_at').notNull().defaultNow(),
});

export const contentActive = contentSchema.table('content_active', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  version_id: varchar('version_id', { length: 36 })
    .references(() => contentVersions.id)
    .notNull()
    .unique(),
  updated_at: timestamp('updated_at').notNull().defaultNow(),
});

// Auth schema
export const authSchema = pgSchema('auth');

export const users = authSchema.table('users', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  email: varchar('email', { length: 255 }).notNull().unique(),
  password_hash: varchar('password_hash', { length: 255 }).notNull(),
  created_at: timestamp('created_at').notNull().defaultNow(),
});

export const sessions = authSchema.table('sessions', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  token: varchar('token', { length: 255 }).notNull().unique(),
  user_id: varchar('user_id', { length: 36 })
    .references(() => users.id)
    .notNull(),
  expires_at: timestamp('expires_at').notNull(),
  created_at: timestamp('created_at').notNull().defaultNow(),
});

// Character schema
export const characterSchema = pgSchema('character');

export const characters = characterSchema.table('characters', {
  id: varchar('id', { length: 36 }).primaryKey().defaultRaw('gen_random_uuid()'),
  user_id: varchar('user_id', { length: 36 })
    .references(() => users.id)
    .notNull(),
  actor_template_id: integer('actor_template_id').notNull(),
  name: varchar('name', { length: 100 }).notNull(),
  base_stats: jsonb('base_stats').notNull(), // snapshot of actor and class stats at creation
  created_at: timestamp('created_at').notNull().defaultNow(),
});

// We'll export a combined schema object for use in drizzle
export const schema = {
  content: {
    drafts: contentDrafts,
    versions: contentVersions,
    active: contentActive,
  },
  auth: {
    users: users,
    sessions: sessions,
  },
  character: {
    characters: characters,
  },
};

import { createClient } from 'redis';
import { config } from 'dotenv';

config();

const redisUrl = process.env.REDIS_URL || 'redis://localhost:6379';

export const redisClient = createClient({
  url: redisUrl,
});

redisClient.on('error', (err) => {
  console.error('Redis Client Error', err);
});

export async function connectRedis() {
  if (!redisClient.isOpen) {
    await redisClient.connect();
  }
}

export async function disconnectRedis() {
  if (redisClient.isOpen) {
    await redisClient.quit();
  }
}

import { AuthService } from './auth.service';
import { FastifyRequest, FastifyReply } from 'fastify';
import { RegisterRequestSchema, LoginRequestSchema } from '@nythera/shared';
import { z } from 'zod';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  async register(request: FastifyRequest, reply: FastifyReply) {
    // Validate request body
    const parseResult = RegisterRequestSchema.safeParse(request.body);
    if (!parseResult.success) {
      reply.status(400).send({ success: false, error: 'Invalid request', details: parseResult.error.format() });
      return;
    }
    const { email, password } = parseResult.data;

    try {
      // Rate limiting for register: we'll use the same Redis key but maybe different? We'll use a separate key for register.
      // We'll allow 5 registrations per 15 minutes per email.
      const redis = require('../../infra/redis').redisClient;
      const attemptsKey = `register_attempts:${email}`;
      const attempts = await redis.get(attemptsKey);
      const attemptCount = attempts ? parseInt(attempts, 10) : 0;
      if (attemptCount >= 5) {
        reply.status(429).send({ success: false, error: 'Too many registration attempts, try again later' });
        return;
      }

      const user = await this.authService.register(email, password);
      // Clear register attempts on success? We'll not clear because we want to limit per email regardless of success? 
      // But if they succeed, they shouldn't need to register again. We'll clear anyway.
      await redis.del(attemptsKey);

      reply.status(201).send({ success: true, data: user });
    } catch (error: any) {
      if (error.code === 'AUTH_USER_EXISTS') {
        reply.status(409).send({ success: false, error: error.message });
      } else {
        console.error('Error in register:', error);
        reply.status(500).send({ success: false, error: 'Internal server error' });
      }
    }
  }

  async login(request: FastifyRequest, reply: FastifyReply) {
    const parseResult = LoginRequestSchema.safeParse(request.body);
    if (!parseResult.success) {
      reply.status(400).send({ success: false, error: 'Invalid request', details: parseResult.error.format() });
      return;
    }
    const { email, password } = parseResult.data;

    try {
      const result = await this.authService.login(email, password);
      reply.send({ success: true, data: result });
    } catch (error: any) {
      if (error.code === 'AUTH_INVALID_CREDENTIALS' || error.code === 'AUTH_RATE_LIMIT_EXCEEDED') {
        reply.status(401).send({ success: false, error: error.message });
      } else {
        console.error('Error in login:', error);
        reply.status(500).send({ success: false, error: 'Internal server error' });
      }
    }
  }

  async logout(request: FastifyRequest, reply: FastifyReply) {
    const authHeader = request.headers.authorization;
    if (!authHeader) {
      reply.status(401).send({ success: false, error: 'Missing token' });
      return;
    }
    const token = authHeader.split(' ')[1];
    if (!token) {
      reply.status(401).send({ success: false, error: 'Missing token' });
      return;
    }

    try {
      await this.authService.logout(token);
      reply.send({ success: true, data: { success: true } });
    } catch (error) {
      console.error('Error in logout:', error);
      reply.status(500).send({ success: false, error: 'Internal server error' });
    }
  }

  async me(request: FastifyRequest, reply: FastifyReply) {
    // The auth middleware will attach request.user
    const userId = request.user?.id;
    if (!userId) {
      reply.status(401).send({ success: false, error: 'Invalid token' });
      return;
    }

    // Fetch user from DB (without password)
    const { db } = require('../../infra/db');
    const { users } = require('../../infra/db/schema');
    const { eq } = require('drizzle-orm');

    const userResult = await db.select().from(users).where(eq(users.id, userId));
    if (userResult.length === 0) {
      reply.status(404).send({ success: false, error: 'User not found' });
      return;
    }
    const user = userResult[0];
    const { password_hash: _, ...userWithoutPassword } = user;
    reply.send({ success: true, data: userWithoutPassword });
  }
}

import { FastifyPluginAsync } from 'fastify';
import { AuthController } from './auth.controller';
import { fp } from 'fastify-plugin';

const authPlugin: FastifyPluginAsync = async (fastify, options) => {
  const authController = new AuthController();

  fastify.post('/auth/register', authController.register.bind(authController));
  fastify.post('/auth/login', authController.login.bind(authController));
  fastify.post('/auth/logout', { preHandler: [req => req.headers.authorization ? undefined : (reply: any) => reply.status(401).send({ success: false, error: 'Missing token' })] }, authController.logout.bind(authController));
  fastify.get('/me', { preHandler: [req => req.headers.authorization ? undefined : (reply: any) => reply.status(401).send({ success: false, error: 'Missing token' })] }, authController.me.bind(authController));
};

export default fp(authPlugin, { name: 'auth' });

import { db } from '../../infra/db';
import { users, sessions } from '../../infra/db/schema';
import { eq } from 'drizzle-orm';
import { randomUUID } from 'crypto';
import { createHash } from 'crypto';
import { redisClient } from '../../infra/redis';
import { config } from 'dotenv';
import { ErrorCodes } from '@nythera/shared';

config();

const SALT_ROUNDS = 12; // for argon2, we'll use the argon2 library's default or we can set time/memory

// We'll use the argon2 library
import argon2 from 'argon2';

export class AuthService {
  async register(email: string, password: string) {
    // Check if user already exists
    const existingUser = await db.select().from(users).where(eq(users.email, email));
    if (existingUser.length > 0) {
      throw { code: ErrorCodes.AUTH_USER_EXISTS, message: 'User already exists' };
    }

    // Hash password
    const passwordHash = await argon2.hash(password);

    // Insert user
    const [user] = await db.insert(users).values({
      id: randomUUID(),
      email,
      password_hash: passwordHash,
    }).returning();

    // Omit password hash from returned user
    const { password_hash: _, ...userWithoutPassword } = user;
    return userWithoutPassword;
  }

  async login(email: string, password: string) {
    // Rate limiting: we'll check Redis for attempts
    // We'll implement a simple fixed window counter per email and IP? For simplicity, we'll do per email.
    // We'll use a key like `login_attempts:${email}`
    // We'll allow 5 attempts per 15 minutes.
    // We'll increment and set expiry if not exists.

    const redis = redisClient;
    const attemptsKey = `login_attempts:${email}`;
    const attempts = await redis.get(attemptsKey);
    const attemptCount = attempts ? parseInt(attempts, 10) : 0;

    if (attemptCount >= 5) {
      throw { code: ErrorCodes.AUTH_RATE_LIMIT_EXCEEDED, message: 'Too many attempts, try again later' };
    }

    // Find user
    const userResult = await db.select().from(users).where(eq(users.email, email));
    if (userResult.length === 0) {
      // Increment attempts and throw generic error to avoid user enumeration
      await redis.incr(attemptsKey);
      await redis.expire(attemptsKey, 900); // 15 minutes
      throw { code: ErrorCodes.AUTH_INVALID_CREDENTIALS, message: 'Invalid credentials' };
    }

    const user = userResult[0];

    // Verify password
    const valid = await argon2.verify(user.password_hash, password);
    if (!valid) {
      // Increment attempts
      await redis.incr(attemptsKey);
      await redis.expire(attemptsKey, 900);
      throw { code: ErrorCodes.AUTH_INVALID_CREDENTIALS, message: 'Invalid credentials' };
    }

    // Clear attempts on successful login
    await redis.del(attemptsKey);

    // Create session
    const token = randomUUID();
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

    await db.insert(sessions).values({
      id: randomUUID(),
      token,
      user_id: user.id,
      expires_at: expiresAt,
    });

    // Store session in Redis for fast lookup? We'll also store in DB.
    // We'll set a Redis key for the session with the user id and expiry.
    await redis.set(`session:${token}`, user.id, {
      EX: Math.floor((expiresAt.getTime() - Date.now()) / 1000),
    });

    // Return user without password and the token
    const { password_hash: _, ...userWithoutPassword } = user;
    return {
      token,
      user: userWithoutPassword,
    };
  }

  async logout(token: string) {
    // Delete session from DB
    await db.delete(sessions).where(eq(sessions.token, token));
    // Delete from Redis
    await redisClient.del(`session:${token}`);
  }

  async validateToken(token: string) {
    // First check Redis for fast lookup
    const userId = await redisClient.get(`session:${token}`);
    if (userId) {
      // We could also verify in DB to ensure it hasn't been revoked, but we'll trust Redis for now.
      // We'll also check the DB to see if the session exists and is not expired.
      const session = await db.select().from(sessions).where(eq(sessions.token, token));
      if (session.length === 0) {
        // Inconsistency: clear Redis and return null
        await redisClient.del(`session:${token}`);
        return null;
      }
      // Check expiration
      const now = new Date();
      if (session[0].expires_at < now) {
        await db.delete(sessions).where(eq(sessions.token, token));
        await redisClient.del(`session:${token}`);
        return null;
      }
      return { userId: session[0].user_id, expiresAt: session[0].expires_at };
    }

    // If not in Redis, check DB
    const session = await db.select().from(sessions).where(eq(sessions.token, token));
    if (session.length === 0) {
      return null;
    }
    const now = new Date();
    if (session[0].expires_at < now) {
      await db.delete(sessions).where(eq(sessions.token, token));
      return null;
    }
    // We'll also set in Redis for next time
    await redisClient.set(`session:${token}`, session[0].user_id, {
      EX: Math.floor((session[0].expires_at.getTime() - Date.now()) / 1000),
    });
    return { userId: session[0].user_id, expiresAt: session[0].expires_at };
  }
}

import { CharacterService } from './character.service';
import { FastifyRequest, FastifyReply } from 'fastify';
import { CreateCharacterRequestSchema } from '@nythera/shared';
import { z } from 'zod';

export class CharacterController {
  private characterService: CharacterService;

  constructor() {
    this.characterService = new CharacterService();
  }

  async createCharacter(request: FastifyRequest, reply: FastifyReply) {
    // Validate request body
    const parseResult = CreateCharacterRequestSchema.safeParse(request.body);
    if (!parseResult.success) {
      reply.status(400).send({ success: false, error: 'Invalid request', details: parseResult.error.format() });
      return;
    }
    const { actorTemplateId, name } = parseResult.data;

    // Get userId from request (set by auth middleware)
    const userId = request.user?.id;
    if (!userId) {
      reply.status(401).send({ success: false, error: 'Unauthorized' });
      return;
    }

    try {
      const character = await this.characterService.createCharacter(userId, actorTemplateId, name);
      reply.status(201).send({ success: true, data: character });
    } catch (error: any) {
      if (error.code === 'CHARACTER_ACTOR_NOT_FOUND' || error.code === 'CHARACTER_CLASS_NOT_FOUND') {
        reply.status(404).send({ success: false, error: error.message });
      } else {
        console.error('Error in createCharacter:', error);
        reply.status(500).send({ success: false, error: 'Internal server error' });
      }
    }
  }

  async getCharacters(request: FastifyRequest, reply: FastifyReply) {
    const userId = request.user?.id;
    if (!userId) {
      reply.status(401).send({ success: false, error: 'Unauthorized' });
      return;
    }

    try {
      const characters = await this.characterService.getCharactersByUserId(userId);
      reply.send({ success: true, data: characters });
    } catch (error) {
      console.error('Error in getCharacters:', error);
      reply.status(500).send({ success: false, error: 'Internal server error' });
    }
  }

  async getCharacterById(request: FastifyRequest, reply: FastifyReply) {
    const userId = request.user?.id;
    if (!userId) {
      reply.status(401).send({ success: false, error: 'Unauthorized' });
      return;
    }
    const { id } = request.params as { id: string };

    try {
      const character = await this.characterService.getCharacterById(id, userId);
      reply.send({ success: true, data: character });
    } catch (error: any) {
      if (error.code === 'CHARACTER_NOT_FOUND') {
        reply.status(404).send({ success: false, error: error.message });
      } else {
        console.error('Error in getCharacterById:', error);
        reply.status(500).send({ success: false, error: 'Internal server error' });
      }
    }
  }
}

