const adminKeyAuth = async (request, reply) => {
  const providedKey = request.headers['x-admin-key'] as string | undefined;
  const expectedKey = process.env.ADMIN_API_KEY;
  if (!providedKey || providedKey !== expectedKey) {
    return reply.status(401).send({ success: false, error: 'Unauthorized' });
  }
};

const contentPlugin: FastifyPluginAsync = async (fastify, options) => {
  const contentController = new ContentController();

  // Register routes with the admin key authentication.
  fastify.post('/admin/content/import', { preHandler: [adminKeyAuth] }, contentController.importContent.bind(contentController));
  fastify.post('/admin/content/publish', { preHandler: [adminKeyAuth] }, contentController.publishContent.bind(contentController));
  fastify.get('/admin/content/active', { preHandler: [adminKeyAuth] }, contentController.getActiveContent.bind(contentController));
};

