import { Isolate } from 'isolated-vm';

// We'll create a simple formula evaluator that uses isolated-vm.
// We'll only support a subset of JavaScript for safety.
// We'll not allow access to the global object, and we'll set a timeout.

// We'll create a pool of isolates? For simplicity, we'll create one isolate per evaluation.
// But note: creating an isolate is expensive. We'll create a single isolate and reuse it with a context.
// However, isolated-vm does not allow resetting the context easily. We'll create a new isolate for each evaluation.
// For now, we'll do that and then we can optimize later.

// We'll define a safe environment: only allow Math and a few globals.
// We'll also set a timeout for the evaluation.

export interface FormulaContext {
  a: Record<string, any>; // attacker
  b: Record<string, any>; // defender
  v: Record<string, any>; // game variables (if needed)
}

export class FormulaEvaluator {
  private isolate: Isolate;

  constructor() {
    this.isolate = new Isolate({ memoryLimit: 128 }); // 128 MB memory limit
  }

  // We'll evaluate a formula string in the context of a and b.
  // We'll return a number.
  // We'll throw if the formula is invalid or if it times out.
  evaluate(formula: string, context: FormulaContext): number {
    // We'll create a new context for the isolate.
    // We'll set up the global template with the context and a safe Math.
    // We'll also set a timeout using isolate.setTimeout? Actually, we can use the isolate's timeout feature.
    // We'll use the isolate's evaluate method with a timeout.

    // We'll wrap the formula in a function that returns the result.
    // We'll also add a check to ensure the result is a number.

    // We'll use the isolate's evaluate method with a timeout of 100ms.
    const contextObject = this.isolate.createContext({
      // We'll expose the context properties as globals? Or we can pass them as arguments.
      // We'll create an object that has a, b, v, and Math.
      a: context.a,
      b: context.b,
      v: context.v || {},
      Math: global.Math, // We'll expose the global Math object.
    });

    // We'll compile the formula as a function that returns the value.
    // We'll use: `return (${formula});`
    // We'll make sure the formula is a valid expression.

    // We'll set a timeout for the evaluation.
    // We'll use the isolate's evaluate method with a timeout option.
    // Note: The timeout option is in milliseconds.

    try {
      const result = this.isolate.evaluateSync(
        `(function() { return (${formula}); })()`,
        {
          context: contextObject,
          timeout: 100, // 100ms timeout
        }
      );

      // We'll check that the result is a number.
      if (typeof result !== 'number' || !isFinite(result)) {
        throw new Error(`Formula did not return a valid number: ${result}`);
      }

      return result;
    } catch (error) {
      // If it's a timeout error, we'll throw a specific error.
      if (error.message.includes('timeout')) {
        throw new Error(`Formula evaluation timed out: ${formula}`);
      }
      throw error;
    } finally {
      // We should release the context? We'll let the isolate be reused for now.
      // We'll dispose the isolate when the evaluator is destroyed? We'll not implement dispose for now.
      // We'll note that we are creating a new isolate per evaluator, so we should dispose it.
      // We'll add a dispose method.
    }
  }

  // We'll add a dispose method to clean up the isolate.
  dispose() {
    this.isolate.dispose();
  }
}

// We'll also create a simple parser that checks for dangerous calls? We'll rely on isolated-vm for safety.
// We'll not implement a full AST parser because isolated-vm already sandboxs.
// We'll just note that we are using isolated-vm and that we are only allowing a subset via the context.

// We'll export a default evaluator instance? We'll not, because we want to allow multiple evaluators if needed.
// We'll leave it to the user to create an instance and dispose it.

// We'll also create a function that evaluates a formula and returns a number, and handles the dispose.
export function evaluateFormula(formula: string, context: FormulaContext): number {
  const evaluator = new FormulaEvaluator();
  try {
    return evaluator.evaluate(formula, context);
  } finally {
    evaluator.dispose();
  }
}

import { z } from 'zod';
import { 
  Actors, Classes, Skills, Items, Weapons, Armors, Enemies, Troops, States, 
  BaseRMObject, RmArray
} from '../schemas/common';
import { System } from '../schemas/system';

// We'll create a normalizer for each file type.
// The normalizer will:
// 1. Parse the JSON with the zod schema (which will filter out nulls and validate the structure?)
//    Actually, our schemas are arrays of nullable objects. Zod will parse and then we can filter out nulls.
// 2. Extract notetags from the `note` field and add a `notetags` field.
// 3. For now, we'll keep the original RM ids (they are 1-based, and we removed the null at index 0).
// 4. We'll also convert the note field to a notetags map and remove the note field? Or keep both?
//    Let's keep both for now, but we can remove the note field if we want to save space.
//    We'll keep the note field for reference and add a notetags field.

// Notetag parser: extract tags like <key>, <key:value>, <key: a, b>
// We'll support:
//   <key> -> { key: true }
//   <key:value> <key:value> -> { key: value }
//   <key: a, b> -> { key: ['a', 'b'] }
//   Also, we can have multiple tags in one note: <key1> <key2:value>
//   We'll split by spaces? But note that the value might contain spaces.
//   We'll use a simple regex to match <...> and then parse the content.

export interface NotetagMap {
  [key: string]: string | string[] | boolean;
}

export function parseNotetags(note: string): NotetagMap {
  const map: NotetagMap = {};
  // Regex to match <...> non-greedy
  const regex = /<([^>]+)>/g;
  let match;
  while ((match = regex.exec(note)) !== null) {
    const content = match[1];
    // Split by colon, but only the first colon because the value might contain colons.
    const parts = content.split(':');
    const key = parts[0].trim();
    if (parts.length === 1) {
      // <key>
      map[key] = true;
    } else {
      const value = parts.slice(1).join(':').trim();
      // Check if the value is a comma-separated list (without spaces? We'll split by comma and trim)
      if (value.includes(',')) {
        const arrayValue = value.split(',').map(v => v.trim()).filter(v => v.length > 0);
        map[key] = arrayValue;
      } else {
        map[key] = value;
      }
    }
  }
  return map;
}

// We'll create a generic normalizer for array-based files.
export function normalizeArrayFile<T extends BaseRMObject>(schema: z.ZodArray<z.ZodNullable<T>>, data: unknown) {
  // Parse the data with the schema (this will throw if invalid)
  const parsed = schema.parse(data);
  // Filter out nulls
  const filtered = parsed.filter((item): item is T => item !== null);
  // For each item, parse notetags and add a notetags field
  const withNotetags = filtered.map(item => ({
    ...item,
    notetags: parseNotetags(item.note),
  }));
  return withNotetags;
}

// For System.json, it's a single object.
export function normalizeSystem(data: unknown) {
  const parsed = System.parse(data);
  // System.json doesn't have a note field? Actually, it might not. But we can still check.
  // We'll just return the parsed object and add a notetags field if there's a note.
  // However, System.json in RM MV doesn't have a note field. We'll skip.
  // But to be consistent, we'll check if there's a note and parse it.
  if (typeof parsed === 'object' && parsed !== null && 'note' in parsed && typeof parsed.note === 'string') {
    return {
      ...parsed,
      notetags: parseNotetags(parsed.note),
    };
  }
  return parsed;
}

// We'll export a function that takes the filename and the data and returns the normalized data.
export function normalizeContent(filename: string, data: unknown) {
  switch (filename) {
    case 'Actors.json':
      return normalizeArrayFile(Actors, data);
    case 'Classes.json':
      return normalizeArrayFile(Classes, data);
    case 'Skills.json':
      return normalizeArrayFile(Skills, data);
    case 'Items.json':
      return normalizeArrayFile(Items, data);
    case 'Weapons.json':
      return normalizeArrayFile(Weapons, data);
    case 'Armors.json':
      return normalizeArrayFile(Armors, data);
    case 'Enemies.json':
      return normalizeArrayFile(Enemies, data);
    case 'Troops.json':
      return normalizeArrayFile(Troops, data);
    case 'States.json':
      return normalizeArrayFile(States, data);
    case 'System.json':
      return normalizeSystem(data);
    default:
      throw new Error(`Unknown file: ${filename}`);
  }
}

